def generate_svg(circuit):
    fname = circuit["filename"]
    path_d = circuit["path"]
    sx, sy = circuit["start"]
    svg_content = f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 500 500" fill="none">
  <!-- Track Outline -->
  <path d="{path_d}" 
        stroke="#e10600" stroke-width="8" stroke-linecap="round" stroke-linejoin="round" />
  <!-- Start / Finish Gate Marker -->
  <circle cx="{sx}" cy="{sy}" r="7" fill="#ffffff" stroke="#e10600" stroke-width="3" />
</svg>
'''
    fpath = os.path.join(SVG_DIR, fname)
    with open(fpath, "w", encoding="utf-8") as f:
        f.write(svg_content)
    return fname

created = []
for c in CIRCUITS_DATA:
    created.append(generate_svg(c))

print(f"Successfully generated {len(created)} circuit SVGs in {SVG_DIR}")
